# Math expression search: normalize expression trees (commutativity, renaming),
# then compare canonical forms.
import ast, re
def canon(node):
    if isinstance(node, ast.BinOp):
        l, r = canon(node.left), canon(node.right)
        op = type(node.op).__name__
        if op in ("Add", "Mult"):
            return "(" + op + " " + " ".join(sorted([l, r])) + ")"
        if op == "Sub": return "(Add " + l + " (Neg " + r + "))"
        return "(" + op + " " + l + " " + r + ")"
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return "(Neg " + canon(node.operand) + ")"
    if isinstance(node, ast.Name): return "VAR"
    if isinstance(node, ast.Constant): return "NUM"
    return "?"
def normalize(expr):
    # tiny LaTeX bridge:  rac{a}{b} -> (a)/(b)
    if expr.startswith("\\frac{"):
        inner = expr[6:]
        a, b = inner[:-1].split("}{")
        expr = "(" + a + ")/(" + b + ")"
    return canon(ast.parse(expr, mode="eval").body)
corpus = {'e1': 'a + b', 'e2': 'a * b', 'e3': 'x + y + z'}
query = r"b + a"
qc = normalize(query)
print("query canonical form:", qc)
for name, expr in corpus.items():
    ec = normalize(expr)
    print(("MATCH " if ec == qc else "      ") + f"{name}: {expr} -> {ec}")

